/* jshint esversion: 8, node: true */
const body = msg.payload || {};
const mapID = body.caltopo_map_id || body.mapID;
const takMission = body.tak_mission_id || body.takMission;

const credId = env.get('CALTOPO_CREDENTIAL_ID');
const credKey = env.get('CALTOPO_CREDENTIAL_KEY');

const errors = [];
if (!mapID) errors.push('caltopo_map_id required');
if (!takMission) errors.push('tak_mission_id required');
if (!credId || !credKey) errors.push('Caltopo credentials env vars missing');

if (errors.length) {
    msg.statusCode = 400;
    msg.headers = {
        'Access-Control-Allow-Origin': '*',
        'Content-Type': 'application/json'
    };
    msg.payload = { added: 0, updated: 0, deleted: 0, conflicts: 0, duration_ms: 0, errors };
    return [null, msg, null];
}

// Concurrency gate: one active run per mapID. Returns 409 on overlap.
// This is a defensive safety net even though correlationId-routing is in use.
const activeKey = 'active_run_' + mapID;
const existing = flow.get(activeKey);
const now = Date.now();
if (existing && existing.expiresAt > now) {
    msg.statusCode = 409;
    msg.headers = {
        'Access-Control-Allow-Origin': '*',
        'Content-Type': 'application/json'
    };
    msg.payload = {
        added: 0, updated: 0, deleted: 0, conflicts: 0, duration_ms: 0,
        errors: ['a sync run for this caltopo_map_id is already in progress'],
        active_correlation_id: existing.correlationId
    };
    return [null, msg, null];
}

const correlationId = 'run_' + now + '_' + Math.random().toString(36).slice(2, 10);
const runStartIso = new Date().toISOString();
const runStartMs = now;
const overallTimeoutMs = 30000;

flow.set(activeKey, {
    correlationId,
    expiresAt: now + overallTimeoutMs + 5000
});

flow.set('run_' + correlationId, {
    res: msg.res,
    req: msg.req,
    mapID: mapID,
    takMission: takMission,
    runStartIso: runStartIso,
    runStartMs: runStartMs,
    activeKey: activeKey,
    counts: {
        caltopo_features: 0,
        tak_features: 0,
        caltopo_errors: 0,
        tak_errors: 0
    },
    errors: []
});

// Trigger message: shape matches what change node a075cdac694b8631 expects
//   payload.mapID, payload.takMission. We deliberately omit msg.res so the
//   legacy phase1extractParams does not steal our response handle (it inspects
//   msg.res and replies 202 if present).
const trigger = {
    payload: { mapID: mapID, takMission: takMission },
    mapID: mapID,
    takMission: takMission,
    correlationId: correlationId,
    _from_plugin_bridge: true
};

// Overall safety-timeout driver. The completion-signal join has its own
// internal timeout (set on the join node), but we also emit an explicit
// timeout message here in case the join never sees either direction emit
// (e.g. both sides have zero work AND no terminal signal arrives).
const timeoutMsg = {
    correlationId: correlationId,
    mapID: mapID,
    runStartIso: runStartIso,
    runStartMs: runStartMs,
    _kind: 'overall_timeout'
};

return [trigger, null, timeoutMsg];

/* jshint esversion: 8, node: true */
// Each per-feature completion signal arrives here. We tag it with the source
// direction (based on link-out id stamped via msg._completionDirection) and
// fan it out to a per-direction debounce trigger. The trigger node emits a
// single "direction-done" message after IDLE_MS of silence (no new feature
// signals for the same correlationId+direction).
//
// CorrelationId propagation (verified):
//   POST /sync/run → trigger msg.correlationId → a075cdac694b8631 (change,
//   additive) → phase1extractParams (Object.assign({}, msg) preserves) →
//   downstream change/function nodes (mutate msg in place OR use {...msg, ...}
//   spread) → terminal debug nodes → link-out → here.
//
// If correlationId is missing (older browser hitting the legacy endpoint, or
// a deep node we did not audit dropping it), we route to /dev/null — the
// signal cannot be attributed to a run.

const correlationId = msg.correlationId;
if (!correlationId) {
    node.warn('completion signal without correlationId; dropping');
    return null;
}

const ctx = flow.get('run_' + correlationId);
if (!ctx) {
    // Completion arriving after we already responded/timed-out. Ignore.
    return null;
}

const direction = msg._completionDirection || 'unknown';

if (direction === 'caltopo') {
    ctx.counts.caltopo_features += 1;
    if (msg.statusCode && msg.statusCode >= 400) ctx.counts.caltopo_errors += 1;
} else if (direction === 'tak') {
    ctx.counts.tak_features += 1;
    if (msg.statusCode && msg.statusCode >= 400) ctx.counts.tak_errors += 1;
}
flow.set('run_' + correlationId, ctx);

// Forward a thin debounce-key message. The trigger node downstream is
// configured to extend its idle timer on every new message with the same
// topic, then emit the held message once IDLE_MS has elapsed without any
// new message.
return {
    correlationId: correlationId,
    topic: correlationId + ':' + direction,
    _kind: 'feature_signal',
    _completionDirection: direction
};

/* jshint esversion: 8, node: true */
// Trigger node fires this after 3s of silence on a (correlationId, direction)
// topic. Re-key for the join node which correlates BOTH directions for the
// same correlationId.
const correlationId = msg.correlationId;
if (!correlationId) return null;

const ctx = flow.get('run_' + correlationId);
if (!ctx) return null; // already finalized

msg.topic = correlationId;
msg.payload = {
    direction: msg._completionDirection,
    counts: Object.assign({}, ctx.counts)
};
return msg;

/* jshint esversion: 8, node: true */
// Fired 30s after run start. If the join has not already finalized the run
// (i.e. flow.get('run_<id>') still exists), emit synthetic done-signals for
// both directions so the join always closes. This handles the empty-side
// case (a direction with zero features never produces a terminal signal).
const correlationId = msg.correlationId;
const ctx = flow.get('run_' + correlationId);
if (!ctx) return null; // already finalized

ctx.timedOut = true;
flow.set('run_' + correlationId, ctx);

const mkSignal = (direction) => ({
    correlationId: correlationId,
    topic: correlationId,
    payload: {
        direction: direction,
        counts: Object.assign({}, ctx.counts),
        synthetic: true
    }
});

return [[mkSignal('caltopo'), mkSignal('tak')]];

/* jshint esversion: 8, node: true */
// Both directions have reported done (or the safety timeout synthesized
// signals). Read counts from flow context, build the response body, and
// hand off to the stale-delete postgres step (which will also stamp
// last_sync_at on sync_pairs and finalize the response).

const grouped = msg.payload || {};
const correlationId = (msg.topic || '').toString();
const ctx = flow.get('run_' + correlationId);
if (!ctx) {
    // Already finalized by a previous path; drop silently.
    return null;
}

// Release the per-mapID concurrency lock.
if (ctx.activeKey) flow.set(ctx.activeKey, undefined);

const durationMs = Date.now() - (ctx.runStartMs || Date.now());

const caltopoCounts = (grouped.caltopo && grouped.caltopo.counts) || ctx.counts;
const takCounts     = (grouped.tak     && grouped.tak.counts)     || ctx.counts;
const syntheticCaltopo = grouped.caltopo && grouped.caltopo.synthetic;
const syntheticTak     = grouped.tak     && grouped.tak.synthetic;

const errors = [];
if (ctx.timedOut) {
    errors.push('overall safety timeout (30s) elapsed; one or both directions may not have completed');
}
if ((caltopoCounts.caltopo_errors || 0) > 0) {
    errors.push((caltopoCounts.caltopo_errors || 0) + ' caltopo-direction HTTP errors');
}
if ((takCounts.tak_errors || 0) > 0) {
    errors.push((takCounts.tak_errors || 0) + ' tak-direction HTTP errors');
}

const body = {
    added: (caltopoCounts.caltopo_features || 0) + (takCounts.tak_features || 0),
    updated: 0,
    deleted: 0,
    conflicts: 0,
    duration_ms: durationMs,
    errors: errors,
    _signal: {
        caltopo_features: caltopoCounts.caltopo_features || 0,
        tak_features: takCounts.tak_features || 0,
        caltopo_synthetic: Boolean(syntheticCaltopo),
        tak_synthetic: Boolean(syntheticTak)
    }
};

msg.payload = `
  WITH stale_delete AS (
    DELETE FROM public.caltopo_maps
     WHERE map_id = $1
       AND COALESCE(seen_on_caltopo_at, 'epoch'::timestamptz) < $2::timestamptz
       AND COALESCE(seen_on_tak_at,     'epoch'::timestamptz) < $2::timestamptz
       AND last_sync_source IS NOT NULL
    RETURNING feature_id
  ),
  conflict_count AS (
    SELECT count(*) AS n FROM public.caltopo_maps
     WHERE map_id = $1
       AND seen_on_caltopo_at >= $2::timestamptz
       AND seen_on_tak_at     >= $2::timestamptz
  ),
  pair_update AS (
    UPDATE public.sync_pairs
       SET last_sync_at = now(),
           last_result  = $3::jsonb
     WHERE caltopo_map_id = $1
       AND tak_mission_id = $4
    RETURNING id
  )
  SELECT (SELECT count(*) FROM stale_delete) AS deleted_count,
         (SELECT n FROM conflict_count)      AS conflict_count,
         (SELECT count(*) FROM pair_update)  AS pair_updated;
`;
msg.queryParameters = [
    ctx.mapID,
    ctx.runStartIso,
    JSON.stringify(body),
    ctx.takMission
];
msg._responseBody = body;
msg._runCtxKey = 'run_' + correlationId;
msg._mapID = ctx.mapID;
msg._takMission = ctx.takMission;
msg.res = ctx.res;
msg.req = ctx.req;
return msg;

/* jshint esversion: 8, node: true */
const row = Array.isArray(msg.payload) ? msg.payload[0] : msg.payload;
const deleted = row ? Number(row.deleted_count || 0) : 0;
const conflicts = row ? Number(row.conflict_count || 0) : 0;
const body = msg._responseBody || {};
body.deleted = deleted;
body.conflicts = conflicts;
msg.payload = body;
msg.statusCode = 200;
msg.headers = msg.headers || {};
msg.headers['Access-Control-Allow-Origin'] = '*';
msg.headers['Access-Control-Allow-Methods'] = 'GET,POST,DELETE,OPTIONS';
msg.headers['Access-Control-Allow-Headers'] = 'Content-Type';
msg.headers['Content-Type'] = 'application/json';
// Clear stashed ctx now that we are about to respond.
if (msg._runCtxKey) flow.set(msg._runCtxKey, undefined);
return msg;

msg.payload = 'SELECT id, caltopo_map_id, tak_mission_id, label, last_sync_at, last_result, created_at FROM public.sync_pairs ORDER BY created_at DESC';
msg.queryParameters = [];
return msg;

msg.payload = Array.isArray(msg.payload) ? msg.payload : [];
msg.statusCode = 200;
msg.headers = {
    'Access-Control-Allow-Origin': '*',
    'Access-Control-Allow-Methods': 'GET,POST,DELETE,OPTIONS',
    'Access-Control-Allow-Headers': 'Content-Type',
    'Content-Type': 'application/json'
};
return msg;

const body = msg.payload || {};
const caltopo_map_id = body.caltopo_map_id;
const tak_mission_id = body.tak_mission_id;
const label = body.label || null;
if (!caltopo_map_id || !tak_mission_id) {
    msg.statusCode = 400;
    msg.headers = {
        'Access-Control-Allow-Origin': '*',
        'Content-Type': 'application/json'
    };
    msg.payload = { error: 'caltopo_map_id and tak_mission_id required' };
    return [null, msg];
}
msg.payload = `
  INSERT INTO public.sync_pairs (caltopo_map_id, tak_mission_id, label)
  VALUES ($1, $2, $3)
  ON CONFLICT (caltopo_map_id, tak_mission_id)
  DO UPDATE SET label = EXCLUDED.label
  RETURNING id, caltopo_map_id, tak_mission_id, label, last_sync_at, last_result, created_at
`;
msg.queryParameters = [caltopo_map_id, tak_mission_id, label];
return [msg, null];

const row = Array.isArray(msg.payload) ? msg.payload[0] : msg.payload;
msg.payload = row || {};
msg.statusCode = 200;
msg.headers = {
    'Access-Control-Allow-Origin': '*',
    'Access-Control-Allow-Methods': 'GET,POST,DELETE,OPTIONS',
    'Access-Control-Allow-Headers': 'Content-Type',
    'Content-Type': 'application/json'
};
return msg;

const id = msg.req && msg.req.params && msg.req.params.id;
if (!id) {
    msg.statusCode = 400;
    msg.headers = {
        'Access-Control-Allow-Origin': '*',
        'Content-Type': 'application/json'
    };
    msg.payload = { error: 'id required' };
    return [null, msg];
}
msg.payload = 'DELETE FROM public.sync_pairs WHERE id = $1 RETURNING id';
msg.queryParameters = [id];
return [msg, null];

const row = Array.isArray(msg.payload) ? msg.payload[0] : msg.payload;
if (!row) {
    msg.statusCode = 404;
    msg.payload = { error: 'pair not found' };
} else {
    msg.statusCode = 200;
    msg.payload = { deleted_id: Number(row.id) };
}
msg.headers = {
    'Access-Control-Allow-Origin': '*',
    'Access-Control-Allow-Methods': 'GET,POST,DELETE,OPTIONS',
    'Access-Control-Allow-Headers': 'Content-Type',
    'Content-Type': 'application/json'
};
return msg;

/* jshint esversion: 8, node: true */
// fs is provided by Setup -> Modules (libs)
//
// v1 synchronous health check. Replaces the prior async multi-branch design
// which hung because the downstream Join used msg.topic as the key but both
// branches set the same topic (correlationId) so count=2 was never reached.
//
// Sub-checks:
//   caltopo_creds_ok  - both env vars set
//   icon_configs_ok   - /data/icon-configs.json parses
//   postgis_ok        - v1 no-op (returns true); /sync/pairs already exercises
//                       postgres so a separate check adds no signal here
//   tak_reachable     - v1 no-op (returns false); skipped to avoid 120s DNS
//                       hangs against TAK_SERVER_URL with no VPN

const credsOk = Boolean(env.get('CALTOPO_CREDENTIAL_ID')) && Boolean(env.get('CALTOPO_CREDENTIAL_KEY'));

let iconConfigsOk = false;
try {
    const raw = fs.readFileSync('/data/icon-configs.json', 'utf8');
    JSON.parse(raw);
    iconConfigsOk = true;
} catch (e) {
    iconConfigsOk = false;
}

msg.payload = {
    caltopo_creds_ok: credsOk,
    postgis_ok: true,
    icon_configs_ok: iconConfigsOk,
    tak_reachable: false
};
msg.statusCode = 200;
msg.headers = {
    'Access-Control-Allow-Origin': '*',
    'Access-Control-Allow-Methods': 'GET,POST,DELETE,OPTIONS',
    'Access-Control-Allow-Headers': 'Content-Type',
    'Content-Type': 'application/json'
};
return msg;
